  "$schema": "http://json-schema.org/draft-04/schema#",
  "type": "object",
  "properties": {
    "meta": {
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"
        },
        "type": {
          "type": "string",
          "enum": [
            "EiffelConfidenceLevelModifiedEvent"
          ]
        },
        "version": {
          "type": "string",
          "enum": [
            "2.0.0"
          ],
          "default": "2.0.0"
        },
        "time": {
          "type": "integer"
        },
        "tags": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "source": {
          "type": "object",
          "properties": {
            "domainId": {
              "type": "string"
            },
            "host": {
              "type": "string"
            },
            "name": {
              "type": "string"
            },
            "serializer": {
              "type": "string",
              "pattern": "^pkg:"
            },
            "uri": {
              "type": "string"
            }
          },
          "additionalProperties": false
        },
        "security": {
          "type": "object",
          "properties": {
            "sdm": {
              "type": "object",
              "properties": {
                "authorIdentity": {
                  "type": "string"
                },
                "encryptedDigest": {
                  "type": "string"
                }
              },
              "required": [
                "authorIdentity",
                "encryptedDigest"
              ],
              "additionalProperties": false
            }
          },
          "additionalProperties": false
        }
      },
      "required": [
        "id",
        "type",
        "version",
        "time"
      ],
      "additionalProperties": false
    },
    "data": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string"
        },
        "value": {
          "type": "string",
          "enum": [
            "SUCCESS",
            "FAILURE",
            "INCONCLUSIVE"
          ]
        },
        "issuer": {
          "type": "object",
          "properties": {
            "name": {
              "type": "string"
            },
            "email": {
              "type": "string"
            },
            "id": {
              "type": "string"
            },
            "group": {
              "type": "string"
            }
          },
          "additionalProperties": false
        },
        "customData": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "key": {
                "type": "string"
              },
              "value": {}
            },
            "required": [
              "key",
              "value"
            ],
            "additionalProperties": false
          }
        }
      },
      "required": [
        "name",
        "value"
      ],
      "additionalProperties": false
    },
    "links": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "type": {
            "type": "string"
          },
          "target": {
            "type": "string",
            "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"
          }
        },
        "required": [
          "type",
          "target"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "meta",
    "data",
    "links"
  ],
  "additionalProperties": false
}

